 "kb1200_evb/kb1200": {
  "identifier": "kb1200_evb/kb1200",
  "name": "KB1200 EVB",
  "vendor": "ene",
  "dts": "kb1200_evb.dts",
  "probeMethods": [
   {
    "id": "openocd",
    "description": "Any SWD/JTAG probe openocd supports — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/jlink.cfg]",
     "transport select swd",
     "source [find target/swj-dp.tcl]",
     "if { [info exists CHIPNAME] } {",
     "set _CHIPNAME $CHIPNAME",
     "} else {",
     "set _CHIPNAME kb1200",
     "}",
     "if { [info exists CPUDAPID ] } {",
     "set _CPUDAPID $CPUDAPID",
     "} else {",
     "set _CPUDAPID 0x2ba01477",
     "}",
     "if { [info exists WORKAREASIZE] } {",
     "set _WORKAREASIZE $WORKAREASIZE",
     "} else {",
     "set _WORKAREASIZE 0x8000",
     "}",
     "swj_newdap $_CHIPNAME cpu -irlen 4 -expected-id $_CPUDAPID",
     "dap create $_CHIPNAME.dap -chain-position $_CHIPNAME.cpu",
     "set _TARGETNAME $_CHIPNAME.cpu",
     "target create $_TARGETNAME cortex_m -endian little -dap $_CHIPNAME.dap",
     "$_TARGETNAME configure -work-area-phys 0x200c0000 -work-area-size $_WORKAREASIZE -work-area-backup 0",
     "adapter speed 600",
     "$_TARGETNAME configure -event reset-start {adapter speed 600}",
     "cortex_m reset_config sysresetreq",
     "flash bank ispif eneispif 0x60000000 0 0 0 $_TARGETNAME 0x50101000"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "KB1200"
   }
  ],
  "console": "uart0",
  "led": {
   "dtSpec": "led0",
   "controller": "gpio0x1x",
   "pin": 15,
   "flags": [
    "GPIO_ACTIVE_HIGH"
   ]
  },
  "button": {
   "dtSpec": "sw0",
   "controller": "gpio0x1x",
   "pin": 16,
   "flags": [
    "GPIO_ACTIVE_LOW",
    "GPIO_PULL_UP"
   ]
  },
  "extraLeds": [
   {
    "dtSpec": "led1",
    "controller": "gpio0x1x",
    "pin": 17,
    "flags": [
     "GPIO_ACTIVE_HIGH"
    ]
   }
  ]
 },
