 "fk723m1_zgt6/stm32h723xx": {
  "identifier": "fk723m1_zgt6/stm32h723xx",
  "name": "FK723M1-ZGT6",
  "vendor": "fanke",
  "dts": "fk723m1_zgt6.dts",
  "probeMethods": [
   {
    "id": "stlink",
    "description": "ST-Link or any SWD probe openocd supports (no BOOT0 needed) — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/stlink-dap.cfg]",
     "transport select dapdirect_swd",
     "set CHIPNAME STM32H723ZG",
     "set WORKAREASIZE 0x3000",
     "set BOARDNAME FM723M1_ZGTV6V1",
     "source [find target/stm32h7x.cfg]",
     "$_CHIPNAME.cpu0 configure -event gdb-attach {",
     "echo \"Debugger attaching: halting execution\"",
     "gdb_breakpoint_override hard",
     "}",
     "$_CHIPNAME.cpu0 configure -event gdb-detach {",
     "echo \"Debugger detaching: resuming execution\"",
     "resume",
     "}"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "STM32H723ZG"
   }
  ],
  "console": "usart1",
  "usbDevice": "enabled",
  "led": {
   "dtSpec": "led0",
   "controller": "gpiog",
   "pin": 7,
   "flags": [
    "GPIO_ACTIVE_LOW"
   ]
  }
 },
 "fk743m5_xih6/stm32h743xx": {
  "identifier": "fk743m5_xih6/stm32h743xx",
  "name": "FANKE FK743M5-XIH6",
  "vendor": "fanke",
  "dts": "fk743m5_xih6.dts",
  "probeMethods": [
   {
    "id": "stlink",
    "description": "ST-Link or any SWD probe openocd supports (no BOOT0 needed) — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/stlink-dap.cfg]",
     "transport select \"dapdirect_swd\"",
     "set WORKAREASIZE 0x8000",
     "set CHIPNAME STM32H743XI",
     "set BOARDNAME FK743M5-XIH6",
     "source [find target/stm32h7x.cfg]",
     "set ENABLE_LOW_POWER 1",
     "set STOP_WATCHDOG 1",
     "reset_config srst_only srst_nogate connect_assert_srst",
     "set CONNECT_UNDER_RESET 1",
     "set CORE_RESET 0"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "STM32H743XI"
   },
   {
    "id": "pyocd",
    "description": "Any CMSIS-DAP probe via pyOCD (no debug)",
    "debug": false,
    "runner": "pyocd",
    "args": [
     "--target=STM32H743XIHx"
    ]
   }
  ],
  "console": "usart1",
  "led": {
   "dtSpec": "led0",
   "controller": "gpioc",
   "pin": 13,
   "flags": [
    "GPIO_ACTIVE_LOW"
   ]
  }
 },
