 "mikroe_mini_m4_for_stm32/stm32f415xx": {
  "identifier": "mikroe_mini_m4_for_stm32/stm32f415xx",
  "name": "Mikroe MINI-M4 for STM32",
  "vendor": "mikroe",
  "dts": "mikroe_mini_m4_for_stm32.dts",
  "probeMethods": [
   {
    "id": "stlink",
    "description": "ST-Link or any SWD probe openocd supports (no BOOT0 needed) — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/stlink-dap.cfg]",
     "transport select dapdirect_swd",
     "set WORKAREASIZE 0x30000",
     "source [find target/stm32f4x.cfg]",
     "adapter speed 1000",
     "adapter srst delay 100",
     "jtag_ntrst_delay 100",
     "reset_config srst_only srst_nogate connect_assert_srst",
     "$_TARGETNAME configure -event gdb-attach {",
     "echo \"Debugger attaching: halting execution\"",
     "reset halt",
     "gdb_breakpoint_override hard",
     "}",
     "$_TARGETNAME configure -event gdb-detach {",
     "echo \"Debugger detaching: resuming execution\"",
     "resume",
     "}"
    ]
   }
  ],
  "console": "usart2",
  "usbDevice": "enabled",
  "led": {
   "dtSpec": "led0",
   "controller": "gpioc",
   "pin": 12,
   "flags": [
    "GPIO_ACTIVE_HIGH"
   ]
  },
  "extraLeds": [
   {
    "dtSpec": "led1",
    "controller": "gpioc",
    "pin": 13,
    "flags": [
     "GPIO_ACTIVE_HIGH"
    ]
   }
  ]
 },
