 "canbardo/same70n20b": {
  "identifier": "canbardo/same70n20b",
  "name": "CANbardo",
  "vendor": "others",
  "dts": "canbardo.dts",
  "probeMethods": [
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "ATSAME70N20B"
   },
   {
    "id": "openocd",
    "description": "Any SWD/JTAG probe openocd supports — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "if {[info exists env(OPENOCD_INTERFACE)]} {",
     "set INTERFACE $env(OPENOCD_INTERFACE)",
     "} else {",
     "set INTERFACE \"cmsis-dap\"",
     "}",
     "source [find interface/$INTERFACE.cfg]",
     "transport select swd",
     "set CHIPNAME atsame70n20b",
     "source [find target/atsamv.cfg]",
     "$_TARGETNAME configure -event gdb-attach {",
     "echo \"Debugger attaching: halting execution\"",
     "reset halt",
     "gdb_breakpoint_override hard",
     "}",
     "$_TARGETNAME configure -event gdb-detach {",
     "echo \"Debugger detaching: resuming execution\"",
     "resume",
     "}"
    ]
   }
  ],
  "console": "uart1",
  "usbDevice": "enabled",
  "led": {
   "dtSpec": "led0",
   "controller": "piod",
   "pin": 9,
   "flags": [
    "GPIO_ACTIVE_LOW"
   ]
  },
  "button": {
   "dtSpec": "sw0",
   "controller": "piod",
   "pin": 15,
   "flags": [
    "GPIO_ACTIVE_LOW"
   ]
  }
 },
