 "decawave_dwm1001_dev/nrf52832": {
  "identifier": "decawave_dwm1001_dev/nrf52832",
  "name": "Decawave-DWM1001-DEV",
  "vendor": "qorvo",
  "dts": "decawave_dwm1001_dev.dts",
  "probeMethods": [
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "nRF52832_xxAA"
   },
   {
    "id": "pyocd",
    "description": "Any CMSIS-DAP probe via pyOCD (no debug)",
    "debug": false,
    "runner": "pyocd",
    "args": [
     "--target=nrf52832"
    ]
   }
  ],
  "console": "uart0",
  "pwmLeds": [
   {
    "alias": "pwm-led0",
    "controller": "pwm0",
    "channel": 0,
    "flags": [
     "PWM_POLARITY_INVERTED"
    ]
   }
  ],
  "led": {
   "dtSpec": "led0",
   "controller": "gpio0",
   "pin": 14,
   "flags": [
    "GPIO_ACTIVE_LOW"
   ]
  },
  "button": {
   "dtSpec": "sw0",
   "controller": "gpio0",
   "pin": 2,
   "flags": [
    "GPIO_PULL_UP",
    "GPIO_ACTIVE_LOW"
   ]
  },
  "extraLeds": [
   {
    "dtSpec": "led1",
    "controller": "gpio0",
    "pin": 30,
    "flags": [
     "GPIO_ACTIVE_LOW"
    ]
   },
   {
    "dtSpec": "led2",
    "controller": "gpio0",
    "pin": 22,
    "flags": [
     "GPIO_ACTIVE_LOW"
    ]
   },
   {
    "dtSpec": "led3",
    "controller": "gpio0",
    "pin": 31,
    "flags": [
     "GPIO_ACTIVE_LOW"
    ]
   }
  ]
 },
