 "longan_nano/gd32vf103": {
  "identifier": "longan_nano/gd32vf103",
  "name": "Sipeed Longan Nano",
  "vendor": "sipeed",
  "dts": "longan_nano.dts",
  "probeMethods": [
   {
    "id": "openocd",
    "description": "Any SWD/JTAG probe openocd supports — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "interface ftdi",
     "ftdi_device_desc \"Dual RS232\"",
     "ftdi_vid_pid 0x0403 0x6010",
     "ftdi_layout_init 0x0008 0x001b",
     "ftdi_layout_signal nSRST -oe 0x0020 -data 0x0020",
     "adapter speed 2000",
     "transport select jtag",
     "proc gd32vf103-pre-load {} {",
     "halt",
     "}",
     "proc gd32vf103-load {file} {",
     "flash protect 0 0 last off",
     "flash write_image erase $file",
     "}",
     "proc gd32vf103-post-verify {} {",
     "mww 0xe004200c 0x4b5a6978",
     "mww 0xe0042008 0x01",
     "resume",
     "}"
    ]
   },
   {
    "id": "dfu",
    "description": "Built-in USB DFU bootloader: hold BOOT0, tap reset (no debug)",
    "debug": false,
    "runner": "dfu-util",
    "args": [
     "--pid=28e9:0189",
     "--alt=0",
     "--dfuse"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "GD32VF103CBT6"
   }
  ],
  "console": "usart0",
  "pwmLeds": [
   {
    "alias": "pwm-led0",
    "controller": "pwm1",
    "channel": 1,
    "flags": [
     "PWM_POLARITY_NORMAL"
    ]
   },
   {
    "alias": "pwm-led1",
    "controller": "pwm1",
    "channel": 2,
    "flags": [
     "PWM_POLARITY_NORMAL"
    ]
   }
  ],
  "led": {
   "dtSpec": "led0",
   "controller": "gpioc",
   "pin": 13,
   "flags": [
    "GPIO_ACTIVE_LOW"
   ]
  },
  "button": {
   "dtSpec": "sw0",
   "controller": "gpioa",
   "pin": 8,
   "flags": [
    "GPIO_ACTIVE_HIGH"
   ]
  },
  "extraLeds": [
   {
    "dtSpec": "led1",
    "controller": "gpioa",
    "pin": 1,
    "flags": [
     "GPIO_ACTIVE_LOW"
    ]
   },
   {
    "dtSpec": "led2",
    "controller": "gpioa",
    "pin": 2,
    "flags": [
     "GPIO_ACTIVE_LOW"
    ]
   }
  ]
 },
