 "apex_pro_mini/stm32l412xx": {
  "identifier": "apex_pro_mini/stm32l412xx",
  "name": "SteelSeries Apex Pro Mini",
  "vendor": "steelseries",
  "dts": "apex_pro_mini.dts",
  "probeMethods": [
   {
    "id": "stlink",
    "description": "ST-Link or any SWD probe openocd supports (no BOOT0 needed) — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/stlink-dap.cfg]",
     "transport select dapdirect_swd",
     "source [find target/stm32l4x.cfg]",
     "reset_config srst_only connect_assert_srst"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "STM32L412RB"
   }
  ],
  "console": "board_cdc_acm_uart",
  "usbDevice": "enabled",
  "led": {
   "dtSpec": "led0",
   "controller": "gpioc",
   "pin": 12,
   "flags": [
    "GPIO_ACTIVE_HIGH"
   ]
  }
 },
 "sr100_rdk/sr100": {
  "identifier": "sr100_rdk/sr100",
  "name": "Synaptics SR100 RDK",
  "vendor": "syna",
  "dts": "sr100_rdk.dts",
  "probeMethods": [
   {
    "id": "openocd",
    "description": "Any SWD/JTAG probe openocd supports — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "adapter driver cmsis-dap",
     "cmsis_dap_vid_pid 0xcafe 0x4006",
     "cmsis_dap_backend hid",
     "transport select swd",
     "adapter speed 1000",
     "reset_config none",
     "set _ENDIAN little",
     "set _CHIPNAME 5312",
     "set _CPUTAPID 0x411fd221",
     "set _TARGETNAME $_CHIPNAME.m55",
     "swd newdap $_CHIPNAME cpu -irlen 4 -expected-id $_CPUTAPID",
     "dap create $_CHIPNAME.dap  -chain-position $_CHIPNAME.cpu -adiv6",
     "$_CHIPNAME.dap apsel  0",
     "$_CHIPNAME.dap apcsw default",
     "target create $_TARGETNAME cortex_m -endian $_ENDIAN -dap $_CHIPNAME.dap -ap-num 0x00010000",
     "$_TARGETNAME configure -event gdb-attach {",
     "halt",
     "}",
     "$_TARGETNAME configure -event gdb-detach {",
     "resume",
     "shutdown",
     "}"
    ]
   }
  ],
  "console": "ns16550_uart1"
 },
 "robokit1/same70q21b": {
  "identifier": "robokit1/same70q21b",
  "name": "TDK RoboKit1",
  "vendor": "tdk",
  "dts": "robokit1.dts",
  "probeMethods": [
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "ATSAME70Q21"
   },
   {
    "id": "openocd",
    "description": "Any SWD/JTAG probe openocd supports — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "if {[info exists env(OPENOCD_INTERFACE)]} {",
     "set INTERFACE $env(OPENOCD_INTERFACE)",
     "} else {",
     "set INTERFACE \"cmsis-dap\"",
     "}",
     "source [find interface/$INTERFACE.cfg]",
     "transport select swd",
     "set CHIPNAME atsame70q21",
     "source [find target/atsamv.cfg]",
     "reset_config srst_only",
     "$_TARGETNAME configure -event gdb-attach {",
     "echo \"Debugger attaching: halting execution\"",
     "reset halt",
     "gdb_breakpoint_override hard",
     "}",
     "$_TARGETNAME configure -event gdb-detach {",
     "echo \"Debugger detaching: resuming execution\"",
     "resume",
     "}"
    ]
   }
  ],
  "console": "uart2",
  "usbDevice": "enabled",
  "led": {
   "dtSpec": "led0",
   "controller": "pioa",
   "pin": 11,
   "flags": [
    "GPIO_ACTIVE_HIGH"
   ]
  }
 },
