 "yd_stm32h750vb/stm32h750xx": {
  "identifier": "yd_stm32h750vb/stm32h750xx",
  "name": "YD-STM32H750VB",
  "vendor": "vcc-gnd",
  "dts": "yd_stm32h750vb.dts",
  "probeMethods": [
   {
    "id": "dfu",
    "description": "Built-in USB DFU bootloader: hold BOOT0, tap reset (no debug)",
    "debug": false,
    "runner": "dfu-util",
    "args": [
     "--pid=0483:df11",
     "--alt=0",
     "--dfuse"
    ]
   },
   {
    "id": "stlink",
    "description": "ST-Link or any SWD probe openocd supports (no BOOT0 needed) — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/stlink-dap.cfg]",
     "transport select dapdirect_swd",
     "set WORKAREASIZE 0x2000",
     "set CHIPNAME STM23H750VB",
     "set BOARDNAME YD_STM23H750VB",
     "source [find target/stm32h7x.cfg]",
     "reset_config srst_only srst_nogate connect_assert_srst",
     "$_CHIPNAME.cpu0 configure -event gdb-attach {",
     "echo \"Debugger attaching: halting execution\"",
     "gdb_breakpoint_override hard",
     "}",
     "$_CHIPNAME.cpu0 configure -event gdb-detach {",
     "echo \"Debugger detaching: resuming execution\"",
     "resume",
     "}",
     "rename init old_init",
     "proc init {} {",
     "old_init",
     "reset halt",
     "}"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "STM32H735IG"
   }
  ],
  "console": "usart1",
  "led": {
   "dtSpec": "led0",
   "controller": "gpioa",
   "pin": 15,
   "flags": [
    "GPIO_ACTIVE_HIGH"
   ]
  },
  "button": {
   "dtSpec": "sw0",
   "controller": "gpiob",
   "pin": 3,
   "flags": [
    "GPIO_ACTIVE_LOW",
    "GPIO_PULL_UP"
   ]
  },
  "extraLeds": [
   {
    "dtSpec": "led1",
    "controller": "gpiob",
    "pin": 4,
    "flags": [
     "GPIO_ACTIVE_HIGH"
    ]
   }
  ]
 },
