 "waveshare_open103z/stm32f103xe": {
  "identifier": "waveshare_open103z/stm32f103xe",
  "name": "Waveshare Open103Z",
  "vendor": "waveshare",
  "dts": "waveshare_open103z.dts",
  "probeMethods": [
   {
    "id": "stlink",
    "description": "ST-Link or any SWD probe openocd supports (no BOOT0 needed) — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/stlink.cfg]",
     "set WORKAREASIZE 0x10000",
     "source [find target/stm32f1x.cfg]",
     "$_TARGETNAME configure -event gdb-attach {",
     "echo \"Debugger attaching: halting execution\"",
     "reset halt",
     "gdb_breakpoint_override hard",
     "}",
     "$_TARGETNAME configure -event gdb-detach {",
     "echo \"Debugger detaching: resuming execution\"",
     "resume",
     "}"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "STM32F103ZE"
   }
  ],
  "console": "usart1",
  "usbDevice": "enabled",
  "led": {
   "dtSpec": "led0",
   "controller": "gpiof",
   "pin": 6,
   "flags": [
    "GPIO_ACTIVE_HIGH"
   ]
  },
  "button": {
   "dtSpec": "sw0",
   "controller": "gpiog",
   "pin": 6,
   "flags": [
    "GPIO_PULL_UP",
    "GPIO_ACTIVE_LOW"
   ]
  },
  "extraLeds": [
   {
    "dtSpec": "led1",
    "controller": "gpiof",
    "pin": 7,
    "flags": [
     "GPIO_ACTIVE_HIGH"
    ]
   },
   {
    "dtSpec": "led2",
    "controller": "gpiof",
    "pin": 8,
    "flags": [
     "GPIO_ACTIVE_HIGH"
    ]
   },
   {
    "dtSpec": "led3",
    "controller": "gpiof",
    "pin": 9,
    "flags": [
     "GPIO_ACTIVE_HIGH"
    ]
   }
  ]
 },
