 "blackpill_f401cc/stm32f401xc": {
  "identifier": "blackpill_f401cc/stm32f401xc",
  "name": "WeAct Studio Black Pill V3.0 (F401CC)",
  "vendor": "weact",
  "dts": "blackpill_f401cc.dts",
  "probeMethods": [
   {
    "id": "dfu",
    "description": "Built-in USB DFU bootloader: hold BOOT0, tap reset (no debug)",
    "debug": false,
    "runner": "dfu-util",
    "args": [
     "--pid=0483:df11",
     "--alt=0",
     "--dfuse"
    ]
   },
   {
    "id": "stlink",
    "description": "ST-Link or any SWD probe openocd supports (no BOOT0 needed) — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/stlink-dap.cfg]",
     "transport select dapdirect_swd",
     "source [find target/stm32f4x.cfg]",
     "reset_config srst_only",
     "$_TARGETNAME configure -event gdb-attach {",
     "echo \"Debugger attaching: halting execution\"",
     "reset halt",
     "gdb_breakpoint_override hard",
     "}",
     "$_TARGETNAME configure -event gdb-detach {",
     "echo \"Debugger detaching: resuming execution\"",
     "resume",
     "}"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "STM32F401CC"
   },
   {
    "id": "blackmagicprobe",
    "description": "Black Magic Probe (no debug)",
    "debug": false,
    "runner": "blackmagicprobe"
   }
  ],
  "console": "usart1",
  "usbDevice": "enabled",
  "led": {
   "dtSpec": "led0",
   "controller": "gpioc",
   "pin": 13,
   "flags": [
    "GPIO_ACTIVE_LOW"
   ]
  },
  "button": {
   "dtSpec": "sw0",
   "controller": "gpioa",
   "pin": 0,
   "flags": [
    "GPIO_ACTIVE_LOW",
    "GPIO_PULL_UP"
   ]
  }
 },
