 "weact_stm32f446_core/stm32f446xx": {
  "identifier": "weact_stm32f446_core/stm32f446xx",
  "name": "WeAct Studio STM32F446 Core Board",
  "vendor": "weact",
  "dts": "weact_stm32f446_core.dts",
  "probeMethods": [
   {
    "id": "dfu",
    "description": "Built-in USB DFU bootloader: hold BOOT0, tap reset (no debug)",
    "debug": false,
    "runner": "dfu-util",
    "args": [
     "--pid=0483:df11",
     "--alt=0",
     "--dfuse"
    ]
   },
   {
    "id": "jlink",
    "description": "J-Link probe (SWD) — also debugs",
    "runner": "jlink",
    "debug": true,
    "debugDevice": "STM32F446RE"
   },
   {
    "id": "stlink",
    "description": "ST-Link or any SWD probe openocd supports (no BOOT0 needed) — also debugs",
    "runner": "openocd",
    "debug": true,
    "debugCfg": [
     "source [find interface/stlink-dap.cfg]",
     "transport select dapdirect_swd",
     "source [find target/stm32f4x.cfg]",
     "reset_config srst_only",
     "$_TARGETNAME configure -event gdb-attach {",
     "echo \"Debugger attaching: halting execution\"",
     "reset halt",
     "gdb_breakpoint_override hard",
     "}",
     "$_TARGETNAME configure -event gdb-detach {",
     "echo \"Debugger detaching: resuming execution\"",
     "resume",
     "}"
    ]
   },
   {
    "id": "pyocd",
    "description": "Any CMSIS-DAP probe via pyOCD (no debug)",
    "debug": false,
    "runner": "pyocd",
    "args": [
     "--target",
     "stm32f446retx"
    ]
   }
  ],
  "console": "usart1",
  "usbDevice": "enabled",
  "led": {
   "dtSpec": "led0",
   "controller": "gpiob",
   "pin": 2,
   "flags": [
    "GPIO_ACTIVE_HIGH"
   ]
  },
  "button": {
   "dtSpec": "sw0",
   "controller": "gpioc",
   "pin": 13,
   "flags": [
    "GPIO_PULL_DOWN",
    "GPIO_ACTIVE_HIGH"
   ]
  }
 },
